def organize_volunteer_schedule(volunteers):
    schedule = {}
    for day in ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]:
        schedule[day] = []

    for volunteer in volunteers:
        name = volunteer["name"]
        available_days = volunteer["available_days"]
