def count_paths(n, x, y, k):
    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < n

    def dfs(x, y, moves_left):
        if moves_left == 0:
            return 1

        count = 0
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            new_x, new_y = x + dx, y + dy
            if is_valid(new_x, new_y):
                count += dfs(new_x, new_y, moves_left - 1)

        return count

    return dfs(x, y, k)

