def find_longest_sequence(song_durations, time_limit):
    max_sequence_length = 0
    start_index = 0
    current_length = 0
    current_sum = 0

    for i in range(len(song_durations)):
        current_sum += song_durations[i]
        current_length += 1

        while current_sum > time_limit:
            current_sum -= song_durations[i - current_length + 1]
            current_length -= 1

        if current_length > max_sequence_length:
            max_sequence_length = current_length
            start_index = i - current_length + 1

    return (max_sequence_length, start_index)

