def analyze_dialectal_variations(words):
    def levenshtein_distance(word1, word2):
        m, n = len(word1), len(word2)
        dp = [[0] * (n + 1) for _ in range(m + 1)]

        for i in range(m + 1):
            dp[i][0] = i
        for j in range(n + 1):
            dp[0][j] = j

        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if word1[i - 1] == word2[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1]
                else:
                    dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1])

        return dp[m][n]

    variations = []
    for word in words:
        found = False
        for variation in variations:
            for var_word in variation:
                if levenshtein_distance(word, var_word) <= 1:
                    variation.add(word)
                    found = True
                    break
            if found:
                break
        if not found:
            variations.append(set([word]))

    return len(variations)

