def manage_reservations(current_reservations, update_reservations):
    available_tables = 20
    reservations = {}

    # Process current reservations
    for reservation in current_reservations:
        time, tables = reservation.split("-")
        reservations[time] = int(tables)
        available_tables -= int(tables)

    # Process updates
    for update in update_reservations:
        if "-Cancel" in update:
            time, tables = update.split("-")[:2]
            tables = int(tables)
            if time in reservations:
                available_tables += reservations[time]
                del reservations[time]
        else:
