    if n < 2:
        return True

    lst.sort()
    min_val = lst[0]
    max_val = lst[-1]

    if max_val - min_val + 1 != n:
        return False

    seen = set()
    for num in lst:
        if num in seen:
            return False
        seen.add(num)

    return True

