def evaluate_correlation(economic_indicators, social_behaviors):
    import numpy as np

    # Handle empty lists
    if not economic_indicators or not social_behaviors:
        return "Error: Lists cannot be empty."

    # Handle lists with single element
    if len(economic_indicators) == 1 or len(social_behaviors) == 1:
        return "Error: Lists must have at least two elements."

    # Check if lists have the same length
    if len(economic_indicators) != len(social_behaviors):
        return "Error: Lists must have the same length."

    # Calculate correlation coefficient
    correlation = np.corrcoef(economic_indicators, social_behaviors)[0, 1]

    # Interpret correlation strength
    if abs(correlation) >= 0.8:
        strength = "strong"
    elif abs(correlation) >= 0.5:
        strength = "moderate"
    elif abs(correlation) >= 0.3:
        strength = "weak"
    else:
        strength = "none"

    return f"The correlation between economic indicators and social behaviors is {strength}."

