def analyze_soap_opera_ratings(input_data):
    soap_opera_ratings = {}

    for soap_opera, episode_num, rating in input_data:
        if soap_opera not in soap_opera_ratings:
            soap_opera_ratings[soap_opera] = [rating, episode_num, rating]
        else:
            current_avg, highest_rated_episode, highest_rating = soap_opera_ratings[soap_opera]
            new_avg = (current_avg * (episode_num - 1) + rating) / episode_num
            if rating > highest_rating or (rating == highest_rating and episode_num < highest_rated_episode):
                soap_opera_ratings[soap_opera] = [new_avg, episode_num, rating]
            else:
                soap_opera_ratings[soap_opera] = [new_avg, highest_rated_episode, highest_rating]

    result = {soap_opera: (avg, highest_rated_episode) for soap_opera, (avg, highest_rated_episode, _) in soap_opera_ratings.items()}
    return result
```

