def is_valid_pawn_move(current_position, target_position):
    # Convert positions to row and column indices
    current_row = 8 - int(current_position[1])
    current_col = ord(current_position[0]) - ord('a')
    target_row = 8 - int(target_position[1])
    target_col = ord(target_position[0]) - ord('a')

    # Check if the move is on the same column
    if current_col != target_col:
        return False

    # Check if the move is valid for a white pawn
    if current_row == 6:
        if target_row == 4:
            return True
        elif target_row == 5:
            return True
        else:
            return False

    # Check if the move is valid for a black pawn
    elif current_row == 1:
        if target_row == 3:
            return True
        elif target_row == 2:
            return True
        else:
            return False

    # Check if the move is one square forward for any pawn
    elif target_row == current_row - 1:
        return True

    # If none of the conditions are met, the move is invalid
    return False

