def compound_interest(principal, annual_rate, times_compounded, years):
    if years == 0:
        return 0.0

    if annual_rate == 0:
        return 0.0

    periodic_rate = annual_rate / (100 * times_compounded)
    compound_periods = times_compounded * years
    future_value = principal * (1 + periodic_rate) ** compound_periods
    interest_earned = future_value - principal

    return round(interest_earned, 2)

