    import re
    from collections import Counter

    def normalize_color(color):
        if color.startswith('#'):
            return color.upper()
        elif color.startswith('rgb'):
            rgb_values = re.findall(r'\d+', color)
            return f'#{int(rgb_values[0]):02X}{int(rgb_values[1]):02X}{int(rgb_values[2]):02X}'.upper()
        else:
            named_colors = {
                'black': '#000000',
                'white': '#FFFFFF',
                'red': '#FF0000',
                'green': '#008000',
                'blue': '#0000FF',
                # Add more named colors as needed
            }
            return named_colors.get(color.lower(), color)

    colors = []
    for style in styles:
        color_matches = re.findall(r'#\w+|rgb\(\d+,\s*\d+,\s*\d+\)|[a-zA-Z]+', style)
        for color in color_matches:
            normalized_color = normalize_color(color)
            colors.append(normalized_color)

    return len(set(colors))

