def tennis_score(points):
    """
    Simulates a simple tennis scoring system for a single game.

    Args:
        points (list): A list of strings representing points won by "player1" or "player2".

    Returns:
        str: The final score of the game in the format "player1_score-player2_score" or "Game player1/player2".
    """
    # Initialize scores for both players
    player1_score = 0
    player2_score = 0

    # Define a dictionary to map scores to their corresponding values
    score_values = {0: 0, 15: 1, 30: 2, 40: 3}

    # Track if a player has advantage
    player1_advantage = False
    player2_advantage = False

    for point in points:
        # Update scores based on the point won
        if point == "player1":
            player1_score = min(player1_score + 1, 4)
            if player2_advantage:
                player2_advantage = False
            elif player1_score == 4 and player2_score < 3:
                return "Game player1"
            elif player1_score == 4 and player2_score == 3:
                player1_advantage = True
        elif point == "player2":
            player2_score = min(player2_score + 1, 4)
            if player1_advantage:
                player1_advantage = False
            elif player2_score == 4 and player1_score < 3:
                return "Game player2"
            elif player2_score == 4 and player1_score == 3:
                player2_advantage = True

        # Handle deuce and advantage cases
        if player1_score == player2_score == 3:
            player1_advantage = False
            player2_advantage = False
        elif player1_advantage and player1_score > player2_score:
            return "Game player1"
        elif player2_advantage and player2_score > player1_score:
            return "Game player2"

    # If the game is not over, return the current score
    player1_score_str = str(list(score_values.keys())[list(score_values.values()).index(player1_score)])
    player2_score_str = str(list(score_values.keys())[list(score_values.values()).index(player2_score)])

    if player1_advantage:
        return f"{player1_score_str}-Adv"
    elif player2_advantage:
        return f"{player2_score_str}-Adv"
    else:
        return f"{player1_score_str}-{player2_score_str}"

