def optimize_park_layout(grid):
    rows = len(grid)
    cols = len(grid[0])

    def is_safe(row, col):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == dc == 0:
                    continue
                r, c = row + dr, col + dc
                if 0 <= r < rows and 0 <= c < cols and grid[r][c] == 'B':
                    return False
        return True

    def place_benches(row, col):
        if row == rows:
            return True

        next_row = row + (col + 1) // cols
        next_col = (col + 1) % cols

        if grid[row][col] == 'O' and is_safe(row, col):
            grid[row][col] = 'B'
            if place_benches(next_row, next_col):
                return True
            grid[row][col] = 'O'

        return place_benches(next_row, next_col)

    place_benches(0, 0)
    return grid

