def analyze_mansion_sales(sales_data, period):
    filtered_sales = [sale for sale in sales_data if period[0] <= sale['sale_year'] <= period[1]]

    if not filtered_sales:
        return {'average_price': None, 'price_increase': None}

    total_sales = sum(sale['sale_price'] for sale in filtered_sales)
    num_sales = len(filtered_sales)
    average_price = total_sales / num_sales

    first_year_sales = [sale for sale in filtered_sales if sale['sale_year'] == period[0]]
    last_year_sales = [sale for sale in filtered_sales if sale['sale_year'] == period[1]]

    if not first_year_sales or not last_year_sales:
        price_increase = None
    else:
        first_year_avg = sum(sale['sale_price'] for sale in first_year_sales) / len(first_year_sales)
        last_year_avg = sum(sale['sale_price'] for sale in last_year_sales) / len(last_year_sales)
        price_increase = ((last_year_avg - first_year_avg) / first_year_avg) * 100

    return {'average_price': average_price, 'price_increase': price_increase}

