def count_escape_routes(grid):
    m, n = len(grid), len(grid[0])
    dp = [[0] * n for _ in range(m)]

    # Base case: Only one way to reach the starting position
    dp[0][0] = 1

    # Fill the dp table row-wise
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    # The value in the bottom-right cell is the number of distinct paths
    return dp[m-1][n-1]

