    if not set(title).issubset(valid_chars):
        return False

    # Check for invalid start or end characters
    if title[0] in string.punctuation + ' ' or title[-1] in string.punctuation + ' ':
        return False

    # Check for consecutive spaces or punctuation marks
    prev_char = None
    for char in title:
        if char in string.punctuation + ' ':
            if prev_char is not None and prev_char in string.punctuation + ' ':
                return False
        prev_char = char

