def spread_smoke(grid):
    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols

    def spread(r, c):
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and grid[nr][nc] == 'H':
                grid[nr][nc] = 'S'

