def find_most_frequent_pattern(strings):
    # Create a dictionary to store the frequency of each pattern
    pattern_freq = {}

    # Iterate through each string
    for string in strings:
        # Generate all possible substrings (patterns)
        for i in range(len(string)):
            for j in range(i + 1, len(string) + 1):
                pattern = string[i:j]
                pattern_freq[pattern] = pattern_freq.get(pattern, 0) + 1

    # Find the pattern with the highest frequency
    max_freq = max(pattern_freq.values())
    most_frequent_patterns = [pattern for pattern, freq in pattern_freq.items() if freq == max_freq]

    # Return the lexicographically smallest pattern
    return min(most_frequent_patterns)

