def calculate_fair_trade_scores(trade_data):
    fair_trade_scores = {}

    for institution, agreements in trade_data.items():
        for agreement in agreements:
            country = agreement['country']
            trade_volume = agreement['trade_volume']
            compliance_score = agreement['compliance_score']
            fair_trade_score = trade_volume * compliance_score

            if country in fair_trade_scores:
                fair_trade_scores[country] += fair_trade_score
            else:
                fair_trade_scores[country] = fair_trade_score

    return fair_trade_scores

