def apply_filter(image, filter_type):
    filtered_image = []
    for row in image:
        filtered_row = []
        for pixel in row:
            if filter_type == "brighten":
                filtered_pixel = min(pixel + 30, 255)
            elif filter_type == "darken":
                filtered_pixel = max(pixel - 30, 0)
            elif filter_type == "invert":
                filtered_pixel = 255 - pixel
            else:
                filtered_pixel = pixel
            filtered_row.append(filtered_pixel)
        filtered_image.append(filtered_row)
    return filtered_image
