def calculate_water_savings(before, after):
    water_savings = {}

    # Create a dictionary to store the water usage for each crop
    before_dict = {crop: usage for crop, usage in before}
    after_dict = {crop: usage for crop, usage in after}

    # Calculate the water savings for each crop
