def recommend_plays(plays, down):
    recommended_plays = []

    if down == 1:
        recommended_plays = ["pass" for play in plays if play == "pass"] + ["run" for play in plays if play == "run"]
    elif down == 2:
        pass_count = plays.count("pass")
        run_count = plays.count("run")
        if pass_count >= run_count:
            recommended_plays = ["pass" for play in plays if play == "pass"]
        else:
            recommended_plays = ["pass" for play in plays if play == "pass"] + ["run" for play in plays if play == "run"]
    elif down == 3:
        if "pass" in plays:
            recommended_plays = ["pass" for play in plays if play == "pass"]
        else:
            recommended_plays = ["run" for play in plays if play == "run"]
    elif down == 4:
        if "punt" in plays:
            recommended_plays = ["punt"]
        else:
            recommended_plays = ["pass" for play in plays if play == "pass"]

    return recommended_plays
