def manage_inventory(inventory, command):
    if command["operation"] == "add":
        new_product = command["product"]
        inventory.append(new_product)
    elif command["operation"] == "update":
        product_name = command["name"]
        new_quantity = command["quantity"]
        for product in inventory:
            if product["name"] == product_name:
                product["quantity"] = new_quantity
                break
    elif command["operation"] == "remove":
        product_name = command["name"]
        inventory = [product for product in inventory if product["name"] != product_name]
    elif command["operation"] == "filter":
        category = command["category"]
        filtered_inventory = [product for product in inventory if product["category"] == category]
        return filtered_inventory
    return inventory

