    if total_sum % 2 != 0:
        return False

    target_sum = total_sum // 2
    dp = set()
    dp.add(0)

    for num in lst:
        temp = set()
        for prev_sum in dp:
            temp.add(prev_sum + num)
        dp.update(temp)

    return target_sum in dp

def find_longest_consecutive_sequence(lst):
