def can_form_palindrome(s):
    # Convert the string to lowercase and remove non-alphanumeric characters
    cleaned_str = ''.join(char for char in s.lower() if char.isalnum())

    # Count the frequency of each character
    char_count = {}
    for char in cleaned_str:
        char_count[char] = char_count.get(char, 0) + 1

    # Check if at most one character has an odd count
    odd_count = 0
    for count in char_count.values():
        if count % 2 != 0:
            odd_count += 1
            if odd_count > 1:
                return False

    # If the length of the cleaned string is even and no character has an odd count,
    # or if the length is odd and exactly one character has an odd count,
    # then the string can form a palindrome
    return True

