    scores.sort(key=lambda x: (-x[1], x[0]))
    return scores[0][0]

def get_old_fossils(fossils, age_threshold):
    old_fossils = []
    for fossil in fossils:
        if fossil['age'] > age_threshold:
            old_fossils.append(fossil['name'])
    return old_fossils

def calculate_total_points(matches):
    total_points = 0
    for match in matches:
        crvena_zvezda_sets, opponent_sets = match
        if crvena_zvezda_sets >= 3:
            total_points += 3
        elif crvena_zvezda_sets == 2:
            total_points += 1
    return total_points

def is_leap_year(year):
    if year % 400 == 0:
        return True
    elif year % 100 == 0:
        return False
    elif year % 4 == 0:
        return True
    else:
        return False

def calculate_total_distance(activities):
    total_distance = 0
    for speed, duration in activities:
        distance = speed * duration
        total_distance += distance
    return total_distance

def simulate_movement(commands, grid_size):
    rows, cols = grid_size
    x, y = 0, 0  # Initial position

    for command in commands:
        if command == "UP":
            new_y = y - 1
            if 0 <= new_y < rows:
                y = new_y
        elif command == "DOWN":
            new_y = y + 1
            if 0 <= new_y < rows:
                y = new_y
        elif command == "LEFT":
            new_x = x - 1
            if 0 <= new_x < cols:
                x = new_x
        elif command == "RIGHT":
            new_x = x + 1
            if 0 <= new_x < cols:
                x = new_x

    return (x, y)

def categorize_artworks(artworks):
    result = {}
    for artwork in artworks:
        year = artwork['year']
        title = artwork['title']
        if year in result:
            result[year].append(title)
        else:
            result[year] = [title]
    return result
